INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (287, 'itIT', 'Kurdran Granmartello$B$BNoto combattente di draghi. Maestro dei Grifoni di Picco dell''Aquila. Comandante della Divisione dei Cavalieri di Grifoni che prese parte alla Spedizione dell''Alleanza che marciò su Draenor, la terra natale degli Orchi. Dato per morto.$B$BSentiremo la chiamata di Sky''ree nel vento. Udiremo il tuo martello tuonare tra le cime delle montagne. Cavalca deciso nell''aldilà, fratello. Le sale dei nostri antenati ti attendono.$B$BGran Thane Falstad Granmartello') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (289, 'itIT', 'Arcimago Khadgar del Kirin Tor$B$BEx apprendista di Medivh. Comandante Supremo della spedizione dell''Alleanza che marciò su Draenor, la terra natale degli Orchi. Dato per morto.$B$BMai nessuno aveva indagato a fondo sul cuore oscuro della magia e della guerra in maniera così altruista. Buona fortuna, pellegrino coraggioso, ovunque tu sia.$B$BAntonidas, Arcimago di Dalaran') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (291, 'itIT', 'Danath Cacciatroll$B$BComandante della Milizia di Stromgarde. Consigliere Tattico del Generale Turalyon, Comandante delle Forze di Spedizione dell''Alleanza che marciarono su Draenor, la terra natale degli Orchi. Dato per morto.$B$BNipote, noi onoriamo la tua memoria e il tuo sacrificio. Sin dalla fondazione del nostro glorioso impero, la strada che porta al valore è stata sempre segnata dal sangue degli eroi.$B$BThoras Cacciatroll, Signore di Stromgarde') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (633, 'itIT', 'Pochi mesi dopo il completamento di Guardiafatua, le energie del Portale Oscuro si unirono, aprendo un nuovo passaggio per Draenor. I clan degli Orchi rimasti, sotto la guida dell''anziano Sciamano Ner''zhul, avanzarono di nuovo verso Azeroth. Determinati a rubare diversi manufatti magici che avrebbero aumentato il potere di Ner''zhul, gli Orchi avevano in mente di aprire nuovi portali in tutta Draenor, per sfuggire una volta per sempre al loro mondo rosso condannato.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (634, 'itIT', 'Convinto che Ner''zhul stesse organizzando una nuova offensiva contro l''Alleanza, Re Terenas di Lordaeron inviò il suo esercito su Draenor per porre fine alla minaccia degli Orchi una volta per tutte. Guidate da Khadgar e dal Generale Turalyon, le forze dell''Alleanza si batterono contro gli Orchi sullo sfondo dello scenario in fiamme. Neanche con l''aiuto della Guardaboschi elfica Alleria, del Nano Kurdran e dell''esperto soldato Danath, Khadgar fu in grado di impedire a Ner''zhul di aprire i suoi portali verso gli altri mondi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (635, 'itIT', 'Le terribili tempeste magiche causate dalle energie convergenti dei portali cominciarono a devastare il mondo. Ner''zhul, seguito solo dai suoi servitori più fedeli, riuscì a fuggire attraverso uno dei portali mentre Khadgar lottava disperatamente per riportare i propri compagni su Azeroth. Resisi conto che sarebbero rimasti intrappolati in quel mondo prossimo alla distruzione, Khadgar e i suoi uomini decisero con un atto d''altruismo di abbattere il Portale Oscuro, per impedire che Azeroth fosse colpita dalla violenta devastazione di Draenor.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (636, 'itIT', 'A quanto pare, gli eroi riuscirono a distruggere il portale e a salvare Azeroth, ma non è chiaro se siano scampati o meno alla distruzione di Draenor.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1591, 'itIT', 'Quest''incudine appartiene a Jordan Stilwell. NON usatela!$B$BJordan') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1752, 'itIT', 'Questi artigli pietrificati sono stati rinvenuti al largo delle coste meridionali di Rovotorto. Secondo gli ecologisti si tratterebbe di un antico Grifalco del Sole. Anche se queste creature compaiono soprattutto nella mitologia dei Tauren, questi artigli fanno pensare che siano esistite davvero.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1753, 'itIT', 'I Geru sono i più grandi uccelli Zampalunga delle Pianure. Ce ne sono pochi ed è raro incontrarli.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1754, 'itIT', 'Questa è una riproduzione in scala dello scheletro di Digrignadenti. Il leggendario montone era una delle meraviglie di Khaz Modan e il protagonista di molti racconti del folklore nanico. A oggi, gli ecologisti non sono riusciti a stabilire le dimensioni e la forza di questa creatura.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1755, 'itIT', 'Quest''uovo, rinvenuto nella remota foresta pluviale del Cratere di Un''Goro, un tempo custodiva un piccolo di gigantosauro. Il suo materiale genetico si è dimostrato assai prezioso per gli ecologisti, che sono vicini a ottenere un siero contro il veleno debilitante dei gigantosauri.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1756, 'itIT', 'Questo scheletro intatto di Pteranodonte è stato recuperato dal remoto Cratere di Un''Goro. A giudicare dalla sua struttura, si tratta di una specie mai avvistata finora. Lo scheletro potrebbe essersi conservato per svariati secoli sotto il terreno fertile della regione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1757, 'itIT', 'Questo astrolabio funzionante, rinvenuto nelle rovine sottomarine di Suramar, fu realizzato dagli Alti Nobili degli Elfi della Notte circa dodicimila anni fa. Gli Alti Nobili erano ossessionati dalla magia, dall''occulto e dall''astronomia, e crearono una serie di dispositivi ingegnosi. Questo in particolare fornisce preziose informazioni sul livello di conoscenze scientifiche degli antichi Elfi della Notte.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1758, 'itIT', 'Questi antichi pezzi di terracotta sono stati recuperati durante gli scavi di Uldaman. Anche se offrono poco in fatto di rune o geroglifici, essi permettono di osservare la maestria e gli accessori quotidiani usati dall''antica razza nanica.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1759, 'itIT', 'Questi cocci scolpiti sono forse la scoperta più importante fatta nelle prime stanze di Uldaman. Le incisioni suggeriscono chiaramente un legame tra i Terrigeni simili a Golem e la razza nanica. Qualora dovessero emergere altri particolari, le nostre teorie sulla creazione da parte dei mitici Titani potrebbero rivelarsi fondate.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1760, 'itIT', 'Questo particolare uovo, rinvenuto nelle infuocate distese del deserto di Tanaris, resta un mistero per gli ecologisti moderni. I test sulla datazione suggeriscono che potrebbe risalire a un migliaio d''anni fa. Anche se certi elementi denotano una struttura insettoide, è impossibile determinare le sue vere origini. Non sono ancora state scoperte delle specie in grado di deporre questo tipo di uova.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1761, 'itIT', 'Questi resti risalenti alla Seconda Guerra servono come monito per ricordare quanto l''Orda sia andata vicina a conquistare la Montagna di Forgiardente.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1865, 'itIT', 'Mentre gli Alti Elfi lottavano per salvarsi dall''attacco furioso dei Troll, gli Umani di Lordaeron, dispersi e nomadi, cercarono di consolidare il controllo sulle proprie terre tribali. Le tribù che diedero i natali all''umanità si attaccarono fra loro, senza alcun riguardo per l''appartenenza alla stessa razza né per l''onore.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1866, 'itIT', 'Eppure una tribù, quella degli Arathi, si accorse che i Troll stavano divenendo una minaccia troppo grande per essere ignorata. Gli Arathi cercarono allora di mettersi a capo di tutte le tribù, in modo da rappresentare un fronte unito contro i guerrieri Troll.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1867, 'itIT', 'Nel giro di sei anni, gli astuti Arathi ebbero la meglio sulle tribù rivali. Dopo ogni vittoria, essi offrirono eguaglianza e pace alle genti conquistate, così riuscirono a ottenere la fedeltà dei vinti. Lentamente la tribù Arathi arrivò a inglobarne molte altre, fino a quando il suo esercito divenne estremamente potente.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1868, 'itIT', 'Fiduciosi di essere in grado di reggere il confronto con i Troll, se non addirittura con gli sfuggenti Elfi in caso di necessità, i signori degli Arathi decisero di costruire una grande città fortificata nelle zone meridionali di Lordaeron. La città-stato prese il nome di Strom e divenne la capitale della nazione degli Arathi, Arathor. Con il prosperare di Arathor, sempre più Umani giunsero a Strom da tutto il continente in cerca di protezione e sicurezza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1869, 'itIT', 'Unite sotto un unico stendardo, le tribù umane svilupparono una vitale cultura. Thoradin, Re di Arathor, sapeva che i misteriosi Elfi nelle terre del nord erano stretti d''assedio dai Troll, ma decise di non rischiare le vite dei propri sudditi per soccorrere degli stranieri. Molti mesi passarono e da nord giunse la notizia della presunta sconfitta degli Elfi. Tuttavia fu solo quando da Quel''Thalas arrivarono ambasciatori trafelati che Thoradin comprese quanto fosse grave la minaccia dei Troll.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1870, 'itIT', 'Gli Elfi dissero a Thoradin che gli eserciti dei Troll erano sconfinati e che, una volta distrutta Quel''Thalas, avrebbero lanciato l''attacco verso sud. Disperati e bisognosi di aiuti militari, gli Elfi accettarono di insegnare ad alcuni Umani l''utilizzo della magia in cambio del loro aiuto contro il nemico.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1871, 'itIT', 'Thoradin, che non si fidava della magia, accettò di assisterli per pura necessità. In brevissimo tempo, degli occultisti elfici giunsero ad Arathor e presero a istruire degli Umani nella via della magia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1872, 'itIT', 'Gli Elfi si accorsero che, anche se gli Umani erano goffi nell''utilizzo delle arti magiche, possedevano una forte affinità naturale verso di essa. A cento uomini vennero svelate le basi della magia degli Elfi: nulla che non fosse assolutamente necessario per combattere i Troll. Convinti che gli apprendisti Umani fossero pronti a unirsi allo scontro, gli Elfi lasciarono Strom e tornarono verso nord, accompagnati dalle possenti armate di Re Thoradin.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1873, 'itIT', 'Le forze congiunte degli Umani e degli Elfi si scontrarono contro le schiere dei Troll ai piedi delle Montagne d''Alterac. La battaglia si protrasse per molti giorni, ma gli eserciti di Arathor non arretrarono mai di un passo di fronte ai Troll che si lanciavano all''assalto. Allora i signori degli Elfi ritennero giunto il momento di scatenare sul nemico la potenza della loro magia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1874, 'itIT', 'I cento Maghi umani e una moltitudine di occultisti elfici fecero appello alla furia dei cieli e scagliarono le fiamme contro l''esercito dei Troll. Il fuoco elementale impedì ai Troll di guarire le proprie ferite e bruciò i loro corpi torturati dall''interno.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1875, 'itIT', 'Le file dei Troll vennero messe in rotta, ma proprio allora l''esercito di Thoradin piombò loro addosso, massacrando fino all''ultimo soldato. I Troll non si sarebbero mai più ripresi del tutto da quella sconfitta e non sarebbero mai riusciti a ricreare una propria nazione. Ora che Quel''Thalas era stata salvata dalla distruzione, gli Elfi strinsero un patto di fedeltà e amicizia con la nazione di Arathor e con la dinastia regale di Thoradin. Umani ed Elfi avrebbero vissuto in armonia nelle ere a venire.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2217, 'itIT', 'In memoria di Jesse Morales') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2295, 'itIT', 'Prima dell''Età della Memoria, la gentile Madre Terra soffiò sopra di noi le dorate nebbie degli albori. Dove quelle auree nubi si posarono, nacquero distese sconfinate di campi di grano e frumento. Quella fu la più grande delle sue opere, il dono della vita e della speranza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2296, 'itIT', 'Lo sguardo della Madre Terra rifulgeva sulle lande che aveva creato con il suo respiro. Il suo occhio destro, An''she (il Sole), donava calore e luce alla terra. L''occhio sinistro, Mu''sha (la Luna), donava pace e riposo alle creature che la abitavano. Tale era il potere del suo sguardo che la Madre Terra chiudeva uno dei suoi occhi a ogni rivoluzione celeste. Così, il suo sguardo amorevole mutò la notte in giorno, con la prima alba del mondo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2297, 'itIT', 'Mentre l''occhio destro creava l''alba dorata, le gentili mani della Madre Terra percorsero le pianure auree. Ovunque passava l''ombra delle sue braccia, dal terreno nasceva una nobile popolazione. Gli Shu''halo (i Tauren) nacquero per lodare e pregare la loro madre amorevole. Là, negli infiniti campi dell''alba, i figli della terra si donarono alla sua grazia e giurarono di benedire il suo nome fino alla fine dei tempi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2298, 'itIT', 'Mentre i figli della terra percorrevano i campi dell''alba, udirono degli oscuri sussurri provenire dalle profondità sotto il mondo. Quelle voci parlarono ai figli delle arti della guerra e dell''inganno. Molti degli Shu''halo caddero sotto le lusinghe dell''ombra e vissero con malizia e perfidia. Si rivoltarono contro i loro fratelli rimasti puri e riversarono la loro innocenza sulle pianure.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2299, 'itIT', 'La Madre Terra, il cuore pesante per le sofferenze dei suoi figli, non sopportava di vederli lontani dalla sua grazia. Nel suo tormento, si strappò gli occhi e li scagliò in una traiettoria senza fine nei cieli stellati. An''she e Mu''sha, cercando di placare a vicenda il proprio dolore, presero a seguire i loro aloni di luce. Da allora i due gemelli si rincorrono, a ogni rivoluzione del mondo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2300, 'itIT', 'La Madre Terra, seppur cieca, non riuscì ad abbandonare il mondo che aveva nel cuore. Si mantenne in ascolto dei venti per scoprire cosa accadeva nei campi dell''alba. Il suo grande cuore era sempre accanto ai suoi figli, la sua saggezza non li abbandonò mai.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2301, 'itIT', 'Nei cuori coraggiosi dei suoi figli rimasti puri, la Madre Terra instillò l''amore per la caccia. Perché le creature della prima alba erano fiere e selvagge. Esse si nascondevano dalla Madre Terra, trovando rifugio nelle ombre e nei luoghi più remoti. Gli Shu''halo cacciavano queste bestie, quando riuscivano a trovarle, e arrivarono ad addomesticarle, con la benedizione della Madre Terra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2302, 'itIT', 'Un grande spirito riuscì però a sfuggire. Apa''ro (conosciuto come Malorne dagli Elfi della Notte) era un fiero cervo, dal manto candido come la neve. Le sue corna sfioravano la vetta dei cieli e i suoi possenti zoccoli scavavano nei recessi del mondo. I Shu''halo diedero la caccia ad Apa''ro nei più remoti angoli del mondo e si avvicinarono a lui per finirlo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2303, 'itIT', 'Nel tentativo di fuggire, il grande cervo spiccò un balzo nel cielo: proprio mentre sembrava salvo, però, le sue enormi corna si impigliarono nelle stelle ed egli rimase bloccato. Anche se lottò per divincolarsi, Apa''ro non si liberò più dal cielo. Fu allora che Mu''sha lo trovò, mentre inseguiva suo fratello An''she verso l''alba. Mu''sha vide il possente cervo di battersi e si innamorò immediatamente di lui.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2304, 'itIT', 'L''astuta Luna strinse un patto con il grande cervo: lo avrebbe liberato dall''intrico delle stelle, se lui in cambio l''avesse amata, ponendo fine alla sua solitudine.\nMu''sha amò Apa''ro e concepì un figlio con lui. Questo figlio, che alcuni definirono un semidio, nacque nelle ombrose foreste della notte. Gli fu dato nome Cenarius ed egli cammina lungo il sentiero stellato che separa il mondo del risveglio da quello dei cieli.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2305, 'itIT', 'Con il passare del tempo, Cenarius crebbe fino a ricordare il suo fiero padre. Fratello degli alberi e delle stelle, il grande cacciatore raggiunse anche i luoghi più remoti del mondo, intonando le armoniose canzoni dell''alba. Tutte le creature si inginocchiavano dinanzi alla sua grazia e alla sua bellezza: nessuno era più astuto del figlio della Luna e del cervo bianco.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2306, 'itIT', 'Cenarius strinse infine amicizia con gli Shu''halo e parlò con loro delle rivoluzioni del mondo. I figli della terra lo riconoscevano come un fratello e promisero di aiutarlo a prendersi cura dei campi della vita e delle creature predilette della Madre Terra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2307, 'itIT', 'Cenarius insegnò ai figli della terra a parlare con alberi e le piante. Gli Shu''halo divennero dei Druidi e operarono grandi prodigi magici, per curare e accudire la terra. Per molte generazioni gli Shu''halo cacciarono insieme a Cenarius e mantennero il mondo al riparo dalle ombre che esistevano sotto di esso.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2308, 'itIT', 'Mentre le nebbie dell''alba svanivano e l''Età della Memoria avanzava a grandi passi, il semidio Cenarius proseguì nella sua strada attraverso i campi del mondo. Gli Shu''halo (i Tauren) furono tristi quando se ne andò e dimenticarono presto le vie dei Druidi che egli aveva mostrato. Con il passare delle generazioni, scordarono come parlare con gli animali e le piante della terra. I sussurri oscuri dagli abissi del mondo arrivarono nuovamente alle loro orecchie.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2309, 'itIT', 'Anche se i figli della terra non diedero ascolto alle voci malvagie, una terribile maledizione si abbatté sulle loro tribù nomadi. Dalle nere lande dell''ovest avanzò infatti un''orda di creature assassine: i Centauri. Cannibali e devastatori, i Centauri colpirono gli Shu''halo come una piaga. I bravi cacciatori si batterono, forti delle benedizioni della Madre Terra nei loro cuori, ma i Centauri non potevano essere sconfitti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2310, 'itIT', 'Gli Shu''halo furono costretti ad abbandonare le loro terre ancestrali e a vagare in eterno attraverso le infinite pianure come nomadi. Si disse che un giorno la speranza sarebbe tornata e che le tribù sparse degli Shu''halo avrebbero trovato una nuova casa tra le amorevoli braccia della Madre Terra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2654, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">UN TRATTATO SUI GRADI MILITARI</H1>\n<BR/>\n<BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRankAlliance" align="left"/>\n<BR/>\n<P align="right">I seguenti sono</P>\n<P align="right">i gradi militari</P>\n<P align="right">dell''Alleanza,</P>\n<P align="right">seguiti da quelli</P>\n<P align="right">per le razze</P>\n<P align="right">conosciute dell''Orda.</P>\n<P align="right">I gradi di ogni fazione</P>\n<P align="right">sono distinti in due sezioni:</P>\n<P align="right">una per gli ufficiali e una per i sottufficiali, in ordine gerarchico, dal più alto al più basso. Lunga vita all''Alleanza!</P>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2655, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEGLI UFFICIALI DELL''ALLEANZA</H1><BR/>\n<P align="center">Parte 1</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\n<P align="right">Gran Maresciallo</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\n<P align="right">Primo Maresciallo</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\n<P align="right">Maresciallo</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\n<P align="right">Comandante</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\n<P align="right">Tenente Comandante</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2656, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEGLI UFFICIALI DELL''ALLEANZA</H1><BR/>\n<P align="center">Parte 2</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">Cavalier Campione</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">Cavalier Capitano</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">Cavalier Tenente</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">Cavaliere</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2657, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEI SOTTUFFICIALI DELL''ALLEANZA</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">Sergente Maggiore</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">Sergente Capo</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">Sergente</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">Caporale</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">Soldato</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2658, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEGLI UFFICIALI DELL''ORDA</H1><BR/>\n<P align="center">Parte 1</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\n<P align="right">Gran Signore della Guerra</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\n<P align="right">Signore della Guerra</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\n<P align="right">Generale</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\n<P align="right">Tenente Generale</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\n<P align="right">Campione</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2676, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI MILITARI DELL''ALLEANZA</H1><BR/>\n<P align="center">UFFICIALI</P><BR/>\n<P align="center">Gran Maresciallo</P>\n<P align="center">Primo Maresciallo</P>\n<P align="center">Maresciallo</P>\n<P align="center">Comandante</P>\n<P align="center">Tenente Comandante</P>\n<P align="center">Cavalier Campione</P>\n<P align="center">Cavalier Capitano</P>\n<P align="center">Cavalier Tenente</P>\n<P align="center">Cavaliere</P><BR/>\n<P align="center">SOTTUFFICIALI</P><BR/>\n<P align="center">Sergente Maggiore</P>\n<P align="center">Sergente Capo</P>\n<P align="center">Sergente</P>\n<P align="center">Caporale</P>\n<P align="center">Soldato</P><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2854, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEGLI UFFICIALI DELL''ORDA</H1><BR/>\n<P align="center">Parte 2</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">Centurione</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">Legionario</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">Guardia di Sangue</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">Guardia di Pietra</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2855, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEI SOTTUFFICIALI DELL''ORDA</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">Primo Sergente</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">Sergente Istruttore</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">Sergente</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">Grunt</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">Esploratore</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2892, 'itIT', 'Qui giacciono i resti di un intrepido Peone, che tentò di combattere ma fece la figura del... fifone.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3163, 'itIT', 'Tartek il Furioso\n\nUno dei più possenti Abomini mai nati dal Flagello, assemblato dal Lich Amnennar l''Araldo del Freddo perché lo aiutasse a creare una base nei Sotterranei di Lamaspina. Tartek ha abbattuto da solo più di 1.200 Verrospino, prima di essere sopraffatto. Il suo sacrificio ha fornito ad Amnennar i corpi necessari a creare un proprio esercito di Verrospino non morti, allestendo così il primo grande avamposto del Flagello a Kalimdor. Una parte dei resti di Tartek sono stati rianimati e usati per creare Ghiotton, l''attuale Luogotenente di Amnennar.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3164, 'itIT', 'Obrahiim il Viaggiatore$B$BArchitetto brillante, elemento chiave nella creazione di Naxxramas e mente dietro la realizzazione di Acherus. Si è fatto rapidamente strada passando da semplice soldato scheletrico a uno dei consiglieri più fidati di Kel''Thuzad. Sempre ansioso di apprendere, Obrahiim ha viaggiato per il mondo in cerca di conoscenza traendo ispirazione dall''architettura dei Nerubiani e dalla magia degli Stregoni Orchi. È stato visto l''ultima volta molti anni fa, diretto a ovest con l''intenzione di studiare le Rovine di Zin-Azshari, a Kalimdor.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3165, 'itIT', 'Diodor il Dannato\n\nNegromante Umano, uno dei primi membri del Culto dei Dannati e famoso eroe durante la Prima Guerra. Guidò con successo un contingente del Flagello alla vittoria durante il primo e il secondo Assalto della Caldamarea al Monastero Scarlatto. È caduto in azione durante il terzo (e ultimo) assalto della Caldamarea, che venne respinto dai soldati della Crociata Scarlatta, ormai a conoscenza del suo modus operandi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3166, 'itIT', 'Kirkessen lo Zelante\n\nUn Lich estremamente potente, agli ordini diretti del Re dei Lich. Veterano decorato di mille battaglie, Kirkessen progettò e guidò l''Assedio Sanguigno, uno dei più grandi assalti organizzati lanciati contro la Cappella della Luce. Nonostante l''attenta pianificazione, il suo attacco fu rapidamente respinto e le sue forze subirono gravissime perdite. Kirkessen stesso fu colpito in modo letale da Ser Maxwell Tyrosus e, da allora, non è più in grado di assumere forma fisica.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3171, 'itIT', 'DRACOMBRA$B$BIl Principe Valanar sta cercando un Cavaliere della Morte in grado di raggiungere Dracombra, la gelida pianura centrale di Nordania, e di guidare una squadra di combattenti scelti in un attacco contro lo Stormo dei Draghi Rossi. "L''addestramento è quasi completo", ha recentemente dichiarato in pubblico. "È giunto il momento di colpire coloro che dovrebbero proteggere i viventi! Gli mostreremo quanto può essere oscuro il destino a Dracombra!".') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3172, 'itIT', 'Alexstrasza, Regina dei Draghi Rossi e nemico più pericoloso del Flagello a Nordania, ha iniziato ad assemblare un proprio esercito, anche se riteniamo che i suoi sforzi siano rivolti al confronto contro i rinnegati dello Stormo dei Draghi Blu.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3211, 'itIT', 'Corpulous grande cuoco di Acherus che prepara buon cibo per voi. Lui fiero di sfamare grande Flagello per renderlo più forte. Non fare arrabbiare Corpulous o lui non sfama più.$B$BRegole:$BCavaliere della Morte mangia per primo, Ghoul aspetta turno.$BGhoul non mangia, prima pulisce piatto.$BBene aggiungere vermi e pidocchi a cibo, Corpulous non offeso.$BAvete vermi? Portate a Corpulous!$BBene mangiare Umani o Elfi. Elfi carne bella bianca.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3212, 'itIT', 'Caos parte di pranzo. Corpulous vede tovagliolo, Corpulous scuote testa per vergogna.$BBene riportare cibo non abbastanza marcio. Corpulous ha tre ascelle per conservare.$BBene mangiare con mani o spade. Non bene mangiare mani o spade.$BZombi devono provare altro cibo. Pensare non solo a cervello.$BNon mangiare se stessi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3213, 'itIT', 'Note sulla creazione di un Dragone del Gelo$B$BLe enormi ossa erano quasi sepolte dalla neve, ma l''artiglio che ne usciva, contorto dall''agonia, era inconfondibile. I negromanti si riunirono senza proferire parola, formando un cerchio attorno al corpo del drago. Rimasero immobili per un momento, mentre il vento li avvolgeva in sbuffi di neve, poi diedero inizio al rituale.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3214, 'itIT', 'Raggi di luce sconsacrata scaturirono dal centro delle ossa congelate, penetrando la neve e il ghiaccio fino a quando l''immensa carcassa si ritrovò interamente esposta. A un gesto del Gran Necrosignore Antiok, le ossa presero a scuotersi e a vibrare, tornando lentamente al loro posto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3215, 'itIT', 'Gli incantesimi dei negromanti iniziarono a riportare la vita in ciò che restava della creatura. Violenti spasmi ne percorsero il corpo, mentre la coscienza del dragone lottava contro quella rigenerazione corrotta. Un lieve grido percorse l''aria e quindi la bestia fu domata. Una gelida luce prese a brillare fra le sue costole, diffondendosi agli arti e portando una sinistra coscienza nelle orbite dei suoi occhi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3216, 'itIT', 'Il Gran Necrosignore si fece avanti e parlò.$B$B"Il Re dei Lich ha deciso di richiamarti in vita per servire il Flagello. Tu sarai il nostro strumento di morte, porterai il tormento sui villaggi dei nostri nemici, ti ciberai dei viventi e porterai sul tuo dorso i nostri più valorosi Cavalieri della Morte".') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3217, 'itIT', 'Il Dragone del Gelo li osservò e chinò il capo, in segno di assenso. La conversione era completa. Arretrando, spalancò le sue ali, proiettandole come mille pugnali nel cielo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3239, 'itIT', 'Vi avevo avvisato che se avessi di nuovo dovuto passare più tempo a pulirmi gli stivali che a calciare bambini ci sarebbero state conseguenze! I turni di pulizia nella latrina sono raddoppiati in durata e numero, per tutti i Geist!\n\nIstruttore Razuvious') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3240, 'itIT', 'Con una notevole ironia, i viventi associano ai non morti tutti i peggiori attributi delle loro stesse esistenze: assenza di speranza, schiavitù, violenza, cattiveria. Noi serviamo! Perché forse i vivi non servono Re, Signori della Guerra, Druidi, Sacerdoti, dei, uomini e bestie? Noi serviamo solo il grande volere del Re dei Lich, che ci conduce verso l''unità e la prosperità!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3241, 'itIT', 'Le azioni degli uomini non hanno fatto altro che generare una serie infinita di tragedie, crudeltà, tradimenti ed egoismo. Il Flagello esiste solo per essere efficiente e unito. Serviamo il Re dei Lich nella vita e continuiamo a farlo anche dopo la morte. Tutte le sue strade portano al raggiungimento di un unico scopo!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3242, 'itIT', 'Freddi nella carne, ma caldi nell''unione. Il potente Flagello è una sola nazione, un solo essere. Il vero gelo sta nello sguardo delle guardie che respingono i profughi della nazione confinante in tempo di guerra! Gli uomini non sono forse tutti uguali? No, perché sono divisi, nel freddo dei loro cuori.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3243, 'itIT', 'Teniamo saldi i nostri ideali e abbattiamo il nemico! I loro caduti andranno a rinfoltire i nostri ranghi, finché tutti serviranno il Trono di Ghiaccio!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3248, 'itIT', 'Oggi sono divenuto un negromante di Thuzadin a Stratholme! Continuo a chiedermi perché nessuno spenga gli incendi e sono rimasto deluso quando ho saputo dell''assurdo sistema delle Ziggurat collegate ai cancelli del mattatoio. Se dobbiamo tenere la gente lontana dal mattatoio, perché non ci limitiamo a chiudere il cancello? Per sempre, magari?') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3249, 'itIT', 'Sto iniziando a capire perché qui le cose funzionano al contrario. Questo arrogante figlio di un cavallo putrefatto è arrivato e si è proclamato "Barone" Fieramorte di Stratholme. Evidentemente ha scambiato il Flagello per una specie di zoo, visto che passa metà del pomeriggio spostando discepoli, servitori e costrutti in piccoli gruppi, posizionandoli ovunque in città!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3250, 'itIT', 'Dopo il completamento della parata per l''ora del tè del Barone, stasera un gruppo di... ehm, chiamiamoli disturbatori, ha iniziato a portare caos. "Chiudiamo i cancelli!", gli ho detto. "I servitori di guardia alle mie Ziggurat proteggeranno il mattatoio, ragazzo!", mi ha risposto. Ho deciso, io me ne vado da qui!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3251, 'itIT', 'Sembra che sia riuscito ad andarmene e, a giudicare dal fumo che si alza dalla città, appena in tempo. Il mio impiego a Stratholme non mi ha procurato alcun beneficio, se non l''anello con sigillo che ho rubato al bastardo. Si tratta di un anello modesto, ma il sigillo del Barone dovrebbe garantirmi l''accesso tra le mura di Naxxramas.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3256, 'itIT', 'Dopo aver accumulato una serie di fallimenti nel tentativo di servire il Flagello, mi sono reso conto di aver bisogno di un qualcosa che sia molto superiore anche a quanto si trova ai livelli più alti dell''organizzazione. Considerata l''inflessibilità insita nelle strutture di comando sociali, è difficile equilibrare i tentativi di apportare mutamenti significativi con le sfide di carattere sociale.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3257, 'itIT', 'Da questo punto di vista è una fortuna che quest''organizzazione offra impieghi a bassa responsabilità a individui non particolarmente motivati o affetti da varie problematiche (nel mio caso, la morte).') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3258, 'itIT', 'Sono qui per abbracciare l''unica verità. L''arrivo della morte è freddo e insoddisfacente, non fornisce alcuna risposta. Sono libero da ogni necessità terrena, vero, ma non avere cuore non è fonte di sollievo. Semplicemente, sono. Posso solo sperare di cadere di nuovo vittima della furia di un cuore nobile e pietoso, in una gloriosa battaglia!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3259, 'itIT', 'La necropoli è stata richiamata alla Corona di Ghiaccio. Abbiamo preso a bordo scorte e personale, e la città è tornata a vivere! Ora sono diverso, mi sento realizzato, vivo. Sento la Sua volontà che mi guida. So esattamente cosa devo fare: quando arriveranno i guerrieri, li metterò alla prova.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3260, 'itIT', 'Cervello. Ceeerrrvvveeelllooo. CCCEEEEERRRRRVVVVVEEEEELLLLLOOOOO!!!$B$B<Continua così per quaranta pagine.>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3269, 'itIT', 'Decreto del Flagello$B$BCapitolo 1$Bdi Kel''Thuzad$B$BLe radici del Flagello affondano nella follia di tutte le razze. La nostra ascesa al potere deriva dai peccati di coloro che vogliono la nostra fine. I cosiddetti "eroi" delle varie terre cadono dinanzi a noi, quando abbracciano i nostri metodi pur di perseguire la vittoria che bramano. Questa loro vittoria è la dimostrazione che, se non fossero ricorsi a ciò che definiscono riprovevole, sarebbero stati sconfitti. In entrambi i casi, perciò, vittoria o sconfitta, il Flagello vince invariabilmente. Quando tutto questo sarà chiaro, la sottomissione alla nostra volontà sarà inevitabile.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3270, 'itIT', 'Il Maestro, il nostro Re dei Lich, è nato seguendo questa stessa dottrina.$BConquistare significa corrompere. Corrompere significa prendere ciò che è giusto e fonte di speranza, ciò che è vivo, e contaminarlo con ogni strumento a nostra disposizione. Gli attributi dei viventi nascondono dentro di sé delle debolezze in grado di annullarli: la speranza è un dogma, la giustizia è fanatismo, la vita è empatia. Occorre capire ciò che fa desiderare la vita ai viventi e distruggerlo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3271, 'itIT', 'Conoscere la via più diretta per ottenere la corruzione è la massima saggezza. Un semplice cedimento del cuore, lo smembramento di organi vitali, una grave malattia sono sufficienti, nella maggior parte dei casi. Il Maestro però non punta alla conquista di molti, ma a quella di tutti. Non serve a nulla sprecare risorse per mutare la mente di un semplice popolano quando basta una semplice piaga, ma similmente è folle tentare con questa piaga di corrompere coloro che sono forti e sani. Bisogna studiare ogni bersaglio per comprenderne le debolezze.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3272, 'itIT', 'Decreto del Flagello$B$BCapitolo 2$B$BIl più grande preconcetto che i viventi hanno nei confronti del Flagello riguarda la nostra propensione per ciò che è considerato "malvagio". Noi permettiamo che questa errata percezione persista, anzi, facciamo di tutto per diffonderla. La vera natura del Flagello è in realtà la trascendenza di ciò che impedisce a ogni razza vivente di ottenere la nostra stessa prosperità.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3273, 'itIT', 'Per esempio: quali benefici derivano realmente dalle emozioni e dall''onore? Servono per dare valore ai viventi, per farli sentire "bene". Dunque, quali sono le loro falsità? L''emozione è direttamente collegata all''ignoranza della logica e della ragione. L''onore, dal canto suo, spesso serve solo a sprecare risorse in una battaglia impossibile da vincere. Non capisco come possano i viventi non capire la nostra impazienza di diventare le loro nemesi per nutrire i loro difetti, diventando la personificazione di tutto ciò che rifugge alla razionalità.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3274, 'itIT', 'L''ambiguità morale non può essere "purificata". L''antipatia non può essere "curata" o "superata". L''avarizia non può essere "annullata", né la collera "guarita". Noi scegliamo di essere la personificazione di tutte queste cose, eppure ci sono ancora degli sciocchi che credono che il Flagello possa essere rimosso e sconfitto completamente. Fino a quando i peccati più comuni dei viventi resteranno la nostra bandiera, ci saranno sempre creature disposte a piegarsi al nostro volere. Io stesso sono nato seguendo questa dottrina.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3275, 'itIT', 'Decreto del Flagello$B$BCapitolo 3$B$BIl Flagello è infinito nel suo potenziale, ma non è comunque infallibile. Dobbiamo essere consapevoli dei nostri limiti e delle risorse a disposizione. Occorre sempre elaborare un piano di fuga. Sacrificare i servitori per raggiungere l''obiettivo è da sempre la base della filosofia del Flagello. Occorre però ricordare che ogni atto di coraggio e martirio che non sia a beneficio del Maestro è una grave imprudenza, severamente punibile.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3276, 'itIT', 'Un altro difetto che gli esterni scorgono nel Flagello è che il nostro potere risiede nella volontà residua dei viventi, che noi siamo visti come una forma avanzata di parassitismo e che senza un ospite capace di rigenerare la vita finiremmo per dissolverci. Ancora una volta non confutiamo quest''assurdità per nostro vantaggio, ma le cose non stanno per nulla così. Noi siamo in realtà una forma in costante miglioramento, capace di adattarsi a una terra sempre più tormentata. Siamo immuni a problemi quali malattia, sovrappopolazione, individualismo, egoismo e persino mortalità. Noi ascoltiamo la volontà del Maestro e lui ci dona tutto ciò che desideriamo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3277, 'itIT', 'Certo, è vero che noi sfruttiamo architettura, tecnologia e capacità fisiche delle culture che assimiliamo. Questo, come molti atti "malvagi" attribuiti al Flagello, è in realtà frutto del nostro pragmatismo. Il Flagello non ha né il tempo, né il desiderio di generare una propria cultura. Un membro del Flagello che crea senza influenza svilupperà un insano attaccamento alla sua creazione, un''aspettativa circa il suo utilizzo. Questo conduce all''individualismo, che conduce alla perdizione. La creatività è un difetto della cultura, ma può essere tollerata quando si applica alla creazione di elementi quali edifici ed equipaggiamenti. Non è nostro compito indagare sull''origine delle nostre risorse: noi dobbiamo soltanto usarle.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3278, 'itIT', 'Il Flagello incarna la volontà della terra. Tutte le forme di vita si inginocchiano dinanzi a noi, con una facilità che spinge verso una sola conclusione: esse hanno bisogno di noi, ci chiedono di essere salvate. È inutile opporre resistenza alle nostre pratiche o cercare riparo dai nostri comandamenti. Noi siamo la conclusione inevitabile per qualsiasi forma di vita naturale: la morte. La morte accompagna ogni vita e con la morte giunge la Non Morte. Prima i vivi riconosceranno questa inevitabile verità, più facile sarà la loro transizione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2858, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">\nAnthony Ray Stark\n</H1>\n<H2 align="center">\n1961 - 2005\n</H2>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (290, 'itIT', 'Generale Turalyon$B$BEx Tenente di Ser Anduin Lothar. Cavaliere della Mano d''Argento. Gran Generale della Spedizione dell''Alleanza che marciò su Draenor, la terra natale degli Orchi. Dato per morto.$B$BEsarus thar no''Darador: noi serviamo nel sangue e nell''onore. Tu eri il braccio destro della giustizia e della virtù, amico mio. Il tuo nome sarà onorato in eterno nelle nostre sale.$B$BSer Uther l''Araldo della Luce, Cavaliere della Mano d''Argento') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1031, 'itIT', '<HTML><BODY>\n\n\n<P>In memoria del mio caro mentore, Horatio M. Montgomery, Medico Guaritore, Istruttore, amico.\n</P>\n<BR/>\n<H1 align="center">\n50 ATG - 25 DTG\n</H1>\n<BR/>\n<P>\n"Il mondo è pieno di persone stanche e ammalate. È nostro dovere come guaritori, ANZI, come uomini e donne di medicina, purificarle TUTTE quante".\n</P>\n<P>\nHoratio M. Montgomery, Medico, Filosofo, Dottore in Giurisprudenza, Gran Maestro Contadino, Ballerino Straordinario, Amico degli Animali</P></BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2661, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI MILITARI DELL''ORDA &amp; DELL''ALLEANZA</H1>\n<BR/>\n<BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRankHorde" align="left"/>\n<BR/>\n<P align="right">Throm''ka!</P>\n<P align="right"> In questo libro</P>\n<P align="right"> troverai l''elenco</P>\n<P align="right">dei gradi militari</P>\n<P align="right">dell''Orda e della</P>\n<P align="right">debole Alleanza.</P>\n<P align="right">Prima vengono quelli</P>\n<P align="right">dell''Orda e poi quelli dell''Alleanza,</P>\n<P align="right">ognuno diviso in ufficiali e sottufficiali, dal più forte al più debole, com''è giusto che sia.</P>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2662, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEGLI UFFICIALI DELL''ORDA</H1><BR/>\n<P align="center">Parte 1</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\n<P align="right">Gran Signore della Guerra</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\n<P align="right">Signore della Guerra</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\n<P align="right">Generale</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\n<P align="right">Tenente Generale</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\n<P align="right">Campione</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2663, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEGLI UFFICIALI DELL''ORDA</H1><BR/>\n<P align="center">Parte 2</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">Centurione</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">Legionario</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">Guardia di Sangue</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">Guardia di Pietra</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2664, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEI SOTTUFFICIALI DELL''ORDA</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">Primo Sergente</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">Sergente Istruttore</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">Sergente</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">Grunt</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">Esploratore</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2665, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEGLI UFFICIALI DELL''ALLEANZA</H1><BR/>\n<P align="center">Parte 1</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\n<P align="right">Gran Maresciallo</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\n<P align="right">Primo Maresciallo</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\n<P align="right">Maresciallo</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\n<P align="right">Comandante</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\n<P align="right">Tenente Comandante</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2856, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEGLI UFFICIALI DELL''ALLEANZA</H1><BR/>\n<P align="center">Parte 2</P>\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\n<P align="right">Cavalier Campione</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\n<P align="right">Cavalier Capitano</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\n<P align="right">Cavalier Tenente</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\n<P align="right">Cavaliere</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2857, 'itIT', '<HTML>\n<BODY>\n<H1 align="center">GRADI DEI SOTTUFFICIALI DELL''ALLEANZA</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">Sergente Maggiore</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">Sergente Capo</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">Sergente</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">Caporale</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">Soldato</P><BR/><BR/>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2905, 'itIT', 'Questa urna contiene le ceneri della mia sanità mentale, della mia passione e del mio spirito, andate distrutte. Possano tutti coloro che osservano le terre desolate della Penisola del Fuoco Infernale ricordarsi di questo Peone caduto. Egli ha versato sangue per l''Alleanza e si è sacrificato per l''Orda, salvo ritrovarsi completamente impazzito per colpa degli esseri malvagi e senz''anima che hanno divorato quello a cui teneva di più. Possano essi subire la sua ira mentre banchettano sulla sua miseria. Forse non in questo mondo, ma in tutti quelli successivi giuro solennemente che vendicherò la mia sofferenza e farò di tutto per mantenere questa promessa.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3226, 'itIT', 'Benvenuto nel Flagello. Ora che hai raggiunto la tua vera dimensione, troverai immenso sollievo scoprendo di essere libero da diversi inconvenienti tipici dei mortali. Non consumerai più il tuo tempo nell''inutile sonno, né avrai bisogno di cercare riparo dagli elementi. Non dovrai più neppure tagliarti le unghie o i capelli! Fantastico!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3227, 'itIT', 'Ci sono comunque alcuni dettagli, quasi insignificanti, da tenere presenti in quanto Non Morto:\n\n-Attenzione alla putrefazione. Un po'' va bene per spaventare i nemici, ma un braccio che si stacca durante una battaglia è fonte di imbarazzo.\n-Impara ad adorare il tuo odore. Alcuni dicono che è orribile, noi diciamo che dà forza.\n-Stai lontano dagli animali viventi, specialmente dai cani.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3228, 'itIT', '-Fa'' attenzione al tuo modo di esprimerti. Se dovessi dislocarti la mascella, potresti essere riassegnato a un incarico dove i gorgoglii non siano fastidiosi. Solitamente non si tratta di incarichi piacevoli.\n-L''alcol non è più la stessa cosa, mi spiace.\n-Un bagno di sangue al giorno leva i vivi di torno (senza bagnoschiuma, però).\n-Evita i colori pastello, non si intonano con il nostro colorito.\n-Nessun vestito ti farà più sembrare grasso.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3229, 'itIT', 'Prendersi Cura dei Ghoul$B$BManuale di rimozione e riciclo') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3230, 'itIT', 'Bende$B$BLe ferite che sanguinano più di tre volte al giorno devono essere bendate. Quando selezioni il tipo di tessuto per le bende, scegli pure quello che preferisci. Molti Ghoul optano per la Telarunica, per via del suo colore viola che tende al marrone quando è inzuppato di sangue. Non si possono comunque ignorare le splendide tonalità giallognole che si ottengono con il lino. Fai qualche prova!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3231, 'itIT', 'Croste e infiammazioni$B$BUna ferita purulenta ricoperta di croste è un ottimo accessorio e aiuta a far capire agli altri come ti senti. Non lasciare che guarisca però, perché una cicatrice mancata è sempre un''occasione sprecata.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3232, 'itIT', 'Insetti$B$BOh, perché non li lasci in pace? Non mangiano poi molto e il loro contributo al tuo aspetto cadente e al tuo devastante fetore è notevole. Se vieni colonizzato da api o vespe, però, recati subito al macello più vicino per cercare aiuto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3233, 'itIT', 'Arti mancanti$B$BLa confusione della battaglia non è certo né il luogo, né il momento giusto per rimpiazzare un arto perduto. Cerca di cavartela con quello che ti è rimasto. Il tuo arto sarà rimpiazzato nel miglior modo possibile non appena un Accolito potrà esaminarti. In caso di estrema necessità, prendi in prestito un arto da un tuo compagno!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3234, 'itIT', 'Cannibalismo$B$BPer evitare il consumo prematuro di personale del Flagello, non puoi mangiare nulla che non sia rimasto immobile al suolo per almeno 5 secondi! Attenzione: i lettini degli Accoliti non vengono considerati suolo!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3378, 'itIT', 'INVINCIBILE$B$BAmato destriero del Principe Arthas Menethil$B$BLeale e dal grande cuore nella vita, possa tu trovare pace nella morte.$B$BAcque pure e verdi pascoli per te, caro amico.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1942, 'itIT', 'Nello stesso periodo in cui Medivh vedeva la luce su Azeroth, Kil''jaeden l''Ingannatore iniziò ad agire per preparare i suoi seguaci nella Distorsione Fatua. L''astuto signore dei demoni, agli ordini del suo padrone Sargeras, pianificava la seconda invasione di Azeroth per mano della Legione Infuocata.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1943, 'itIT', 'Questa volta non avrebbe tollerato errori. Kil''jaeden si era reso conto di aver bisogno di una forza che indebolisse le difese di Azeroth ancor prima che la Legione tornasse nel mondo. Se le razze mortali, come Elfi della Notte e draghi, fossero state costrette a fronteggiare una nuova minaccia, non sarebbero state capaci di resistere all''offensiva della Legione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1944, 'itIT', 'Fu in quel periodo che Kil''jaeden scoprì il lussureggiante mondo di Draenor, che fluttuava pacificamente nella Grande Oscurità. Dimora dei clan sciamanici degli Orchi e dei pacifici Draenei, Draenor era un luogo tanto idilliaco quanto vasto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1945, 'itIT', 'I nobili clan degli Orchi si spostavano per le praterie e cacciavano per diletto, mentre i curiosi Draenei realizzavano spigolose città sui pendii più inaccessibili di quel mondo. Kil''jaeden comprese che gli abitanti di Draenor sarebbero stati dei servitori perfetti per la Legione Infuocata, se adeguatamente addestrati.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1946, 'itIT', 'Delle due razze, Kil''jaeden ritenne che quella degli Orchi avrebbe ceduto più facilmente alla corruzione della Legione. Riuscì ad ammaliare il più anziano Sciamano degli Orchi, Ner''zhul, esattamente come in passato Sargeras aveva fatto con la Regina Azshara. Usando l''astuto Sciamano come suo tramite, il demone trasmise la sete di sangue e la furia assassina fra i clan degli Orchi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1947, 'itIT', 'Non trascorse molto tempo prima che quella razza spirituale fosse trasformata in un popolo sanguinario. Kil''jaeden allora spinse Ner''zhul e la sua gente oltre l''ultimo limite: consegnarsi interamente a lui in nome della morte e della guerra. Eppure il vecchio Sciamano, resosi conto che il suo popolo sarebbe stato per sempre schiavo dell''odio, riuscì in qualche modo a opporsi al comando del demone.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1948, 'itIT', 'Frustrato dalla resistenza di Ner''zhul, Kil''jaeden cercò un altro Orco disposto a consegnare la sua gente nelle mani della Legione. L''astuto signore dei demoni trovò infine il discepolo che cercava nell''ambizioso apprendista di Ner''zhul, Gul''dan. Kil''jaeden promise a Gul''dan poteri smisurati in cambio della sua obbedienza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1949, 'itIT', 'Il giovane Orco divenne un avido studente della magia demoniaca, tramutandosi in breve nel più potente Stregone mortale della storia. Egli insegnò ad altri giovani Orchi le arti arcane, cercando di spazzare via le tradizioni sciamaniche del suo popolo. Gul''dan mostrò ai suoi simili una nuova magia e un nuovo tremendo potere.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1950, 'itIT', 'Kil''jaeden, intenzionato ad accrescere il suo controllo sugli Orchi, aiutò Gul''dan a fondare il Concilio dell''Ombra, una setta segreta che manipolò i clan degli Orchi e diffuse la magia degli Stregoni in tutto Draenor. Mentre sempre più Orchi abbracciavano il nuovo potere, i rigogliosi campi di Draenor divennero aridi. Ben presto le vaste praterie che per lungo tempo avevano ospitato gli Orchi svanirono, lasciando il posto a lande desolate. Le energie demoniache stavano lentamente uccidendo quel mondo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2891, 'itIT', 'In ricordo del Comandante Supremo dell''Alleanza, Anduin Lothar: un uomo che avrebbe sacrificato tutto per difendere il suo Re, la sua gente e la sua terra...\n\nChe i nostri nemici conoscano i nostri nomi e che i nostri alleati onorino la nostra morte, perché noi siamo i Figli di Lothar.\n\nGenerale Turalyon') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3102, 'itIT', 'In tributo a Re Varian Wrynn, conosciuto anche come LO''GOSH il "Lupo Spettrale"$B$BIl suo miracoloso ritorno, dopo lunghi anni di esilio e tribolazioni, ha dato nuova forza e nuovo coraggio all''Alleanza. Marceremo fieri in queste terre pericolose con il suo valore e la sua tenacia nei nostri cuori.$B$BGran Signore Bolvar Domadraghi') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3167, 'itIT', 'NORDANIA OCCIDENTALE$B$BI rapporti dello Squadrone di Ricognizione Aerea sul Ghiacciaio delle Ossa segnalano che la comunicazione con il Signore dei Lich Gelinverno si è bruscamente interrotta. "Gelinverno è stato visto l''ultima volta mentre guidava la necropoli, Talramas, sopra la Tundra Boreale per una missione segreta," segnala l''Ingegnere del Flagello Karomon, l''ufficiale addetto alle informazioni dello Squadrone. "L''esame diagnostico indica che i cristalli di comunicazione funzionano perfettamente... ma nessuno risponde.".') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3193, 'itIT', 'Cavalieri della Morte di Acherus$B$BNome: Jayde$BStato: in vita$BNote: sempre più potente. Ottima tattica. Di più brutale c''è soltanto $n.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3194, 'itIT', 'Nome: Sixen$BStato: deceduto$BNote: è morto con la bocca aperta.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3195, 'itIT', 'Nome: Munch$BStato: in vita$BNote: non esita mai. Araldo della Rovina.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3196, 'itIT', 'Nome: Cobalt$BStato: in vita*$BNote: sono stati finalmente trovati dei pezzi di questo Cavaliere della Morte. Uniti, hanno dato vita a un Abominio furioso. Testa e cervello inceneriti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3197, 'itIT', 'Nome: Harmony$BStato: deceduto$BNote: il nome di questo Cavaliere della Morte era in violazione delle norme di decenza del Flagello. Eliminato dal Re dei Lich.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3198, 'itIT', 'Nome: Melt$BStato: in vita*$BNote: tramutato in Ghoul. Ucciso da un Popolano Scarlatto. Rianimato da Munch come servitore Ghoul.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3199, 'itIT', 'Nome: Milton$BStato: giustiziato$BNote: catturato. È stato trovato, senza armatura e lama runica, mentre dormiva accanto al Nerodestriero. Quest''ultimo è stato restituito a Salanar, senza gravi danni. I Cavalieri della Morte non possono dormire.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3200, 'itIT', 'Nome: Minitalis$BStato: dispersa$BNote: si ignora dove sia. Le ricerche proseguono.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3201, 'itIT', 'Nome: $n$BStato: in vita$BNote: macchina della morte senz''anima. Nessun rimorso, nessun senso di colpa. Ha ucciso più Crociati Scarlatti e causato più devastazioni di qualsiasi altro Cavaliere della Morte che l''ha $gpreceduto:preceduta;. $GPromosso:Promossa; a Comandante del Flagello.$B$B<Il libro prosegue per centinaia di pagine.>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3202, 'itIT', 'Cavalieri della Morte di Acherus$B$BNome: Jayde$BStato: in vita$BNote: Campionessa di Mograine. Diretta verso la Cappella della Luce. La distruzione è assicurata.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3203, 'itIT', 'Nome: Sixen$BStato: deceduto$BNote: è morto con la bocca aperta.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3204, 'itIT', 'Nome: Munch$BStato: in vita$BNote: promosso a Comandante del Flagello. Mi accompagnerà a Nordania.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3205, 'itIT', 'Nome: Cobalt$BStato: deceduto$BNote: l''Abominio furioso creato con i pezzi di questo Cavaliere della Morte è stato abbattuto dagli eserciti di Tirisfal: l''unico momento degno di nota per lui dopo la rinascita.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3206, 'itIT', 'Nome: Harmony$BStato: deceduto*$BNote: il nome di questo Cavaliere della Morte è in violazione delle norme di decenza del Flagello. Eliminato dal Re dei Lich.$B$B*Il Re dei Lich ha ordinato che i resti di questo Cavaliere della Morte siano bruciati e le ceneri disperse in una latrina umana. Al Re dei Lich non piace che si scherzi con i nomi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3207, 'itIT', 'Nome: Melt$BStato: in vita*$BNote: tramutato in Ghoul. Ucciso da un Popolano Scarlatto. Rianimato da Munch come servitore Ghoul. Melt si sta comportando egregiamente come servitore: è anche un ottimo cuoco.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3208, 'itIT', 'Nome: Milton$BStato: giustiziato*$BNote: catturato. È stato trovato, senza armatura e lama runica, mentre dormiva accanto al Nerodestriero. Quest''ultimo è stato restituito a Salanar, senza gravi danni.$B$B*Il Nerodestriero non ce l''ha fatta.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3209, 'itIT', 'Nome: Minitalis$BStato: traditrice$BNote: la troveremo e porremo fine alla sua miserabile esistenza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3210, 'itIT', 'Nome: $n$BStato: in vita$BNote: $gil:la; Comandante del Flagello $n ha ricevuto la Celata del Flagello dal Re dei Lich, in cambio dei servigi resi contro gli eserciti di Tirisfal e Valsalda. Nessuno è sopravvissuto ai brutali attacchi di $n. Al momento è in viaggio verso l''Alba d''Argento.$B$B<Il libro prosegue per centinaia di pagine.>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3252, 'itIT', 'Oggi ho iniziato a lavorare in un laboratorio militare del grande Flagello! Naxxramas pulsa di un''attività frenetica. Mi è dispiaciuto scoprire che utilizzano assurdi meccanismi enigmatici per fornire energia a dei teletrasporti di importanza vitale, ma a parte questo sembra tutto a posto. Mi sono così dedicato a interessanti ricerche, fino a quando non mi sono imbattuto nel perverso Nerubiano...') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3253, 'itIT', 'Il Nerubiano continua a contattarmi, chiamandomi con quella sua voce che mette i brividi. Mi invita a studiare nel suo "salotto". Ho preso l''abitudine di restarmene all''interno della conduttura rotta dietro le camere di Gluth, dato che è l''unico luogo dove mi lascia in pace. Non ce la faccio più!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3254, 'itIT', 'Com''è possibile che questa squadra raffazzonata di disadattati e cadaveri in putrefazione pensi di conquistare Azeroth? La loro ridicola convinzione sembra andare contro anche alle più elementari regole dell''autoconservazione! E io non posso far nulla per mutare la situazione, non con quel detestabile Nerubiano che continua a tormentarmi!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3255, 'itIT', 'Ormai sembra quasi una costante: ogni volta che ho a che fare con il Flagello, degli avventurieri penetrano nella necropoli uccidendo i miei colleghi. Anche la splendida rossa del culto di Faerlina è stata uccisa, prima che quel ragno spaventoso mi permettesse anche solo di rivolgerle la parola! Odio questo posto. Non appena sarò un Non Morto me ne andrò. È ora di combattere!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3544, 'itIT', 'Hai trovato i resti di un misterioso oggetto. Oltre le fiamme riesci a scorgere un marchio con su scritto: "M:1815212085". Ti chiedi da quale mondo provenga...') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (637, 'itIT', 'Diecimila anni prima che gli Orchi e gli Umani si scontrassero nella Prima Guerra, il mondo di Azeroth era formato da un solo enorme continente circondato dal mare. Quell''ammasso di terra conosciuto come Kalimdor ospitava numerose razze e creature diverse, tutte impegnate a lottare per la sopravvivenza in quell''ambiente ostile che era il mondo della veglia. Al centro del continente oscuro c''era un misterioso lago di energie incandescenti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (638, 'itIT', 'Ribattezzato in seguito Pozzo dell''Eternità, era il cuore della magia e del potere naturale del mondo. Assorbendo l''energia dall''infinita Grande Oscurità, il Pozzo fungeva da fonte mistica, alimentando la vita in tutte le sue splendide forme.$B$BUna tribù primitiva di umanoidi notturni si spinse cautamente fino alle rive dello splendido lago incantato.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (639, 'itIT', 'Attratti dalle strane energie del Pozzo, questi feroci umanoidi nomadi si stabilirono lungo le sue placide sponde. Col tempo il potere cosmico del Pozzo influenzò la tribù, rendendola forte, saggia e di fatto immortale. La tribù prese il nome di Kaldorei, figli delle stelle nella loro lingua nativa. Per festeggiare la nascita della loro società, furono erette grandi strutture e templi intorno al lago.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (640, 'itIT', 'I Kaldorei, o Elfi della Notte come si sarebbero chiamati più tardi, adoravano la Dea della Luna Elune e credevano che essa riposasse nelle profondità delle acque luccicanti del Pozzo durante il giorno. I primi sacerdoti e veggenti degli Elfi della Notte studiarono il Pozzo con morbosa curiosità, decisi a svelarne i segreti e i poteri. Man mano che la loro società cresceva, gli Elfi della Notte esplorarono Kalimdor in lungo e in largo, entrando in contatto con gli altri suoi abitanti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (641, 'itIT', 'Le uniche creature di fronte alle quali esitarono furono gli antichi e potenti draghi. Le grandi bestie serpentiformi vivevano spesso isolate, ma si diedero molto da fare per difendere le terre conosciute da potenziali minacce. Gli Elfi della Notte scoprirono che i draghi si consideravano i protettori del mondo e decisero di lasciarli in pace insieme ai loro segreti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (642, 'itIT', 'Col tempo la curiosità degli Elfi della Notte li portò a conoscere e a farsi amiche diverse entità potenti, non ultimo Cenarius, un importante semidio delle foreste primordiali. Il nobile Cenarius si affezionò ai curiosi Elfi della Notte e trascorse parecchio tempo con loro a istruirli sul mondo naturale. I pacifici Kaldorei svilupparono un forte legame con le foreste viventi di Kalimdor e si trovavano a proprio agio nell''armonioso equilibrio della natura.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (643, 'itIT', 'Con il passare delle ere apparentemente infinite, la civiltà degli Elfi della Notte si espanse sia a livello territoriale sia culturale. I loro templi, le loro strade e le loro dimore si trovavano in tutto il continente oscuro. Azshara, la splendida e intelligente regina degli Elfi della Notte, fece costruire un magnifico e immenso palazzo sulle sponde del Pozzo per ospitare i suoi servitori più fidati all''interno delle sale ornate di gioielli.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (644, 'itIT', 'I suoi servitori, che lei chiamava Quel''dorei, o Alti Nobili, obbedivano a ogni suo ordine e si ritenevano superiori al resto dei loro fratelli. Mentre la Regina Azshara era amata in egual misura da tutto il suo popolo, gli Alti Nobili erano odiati in segreto dal resto degli Elfi della Notte.$B$BCondividendo la stessa curiosità dei sacerdoti per il Pozzo dell''Eternità, Azshara ordinò agli Alti Nobili di svelarne i segreti e scoprire il suo vero scopo nel mondo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (645, 'itIT', 'Questi si gettarono a capofitto nelle loro ricerche e studiarono il Pozzo incessantemente. Col tempo svilupparono la capacità di manipolare e controllare le energie cosmiche del Pozzo. Man mano che conducevano i loro esperimenti, si accorsero che avrebbero potuto usare i nuovi poteri per creare o distruggere a loro piacimento. Gli incauti Alti Nobili si erano imbattuti nella magia primitiva ed erano decisi a padroneggiarla.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (646, 'itIT', 'Nonostante sapessero che la magia era pericolosa se usata in modo irresponsabile, Azshara e i suoi Alti Nobili si abbandonarono alla pratica indiscriminata delle arti magiche. Cenarius e molti saggi studiosi degli Elfi della Notte li misero in guardia dal condurre esperimenti con la magia, sottolineando che da essa potevano scaturire solo effetti devastanti. Ma Azshara e i suoi seguaci continuarono ostinatamente a espandere e sviluppare i loro poteri.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (647, 'itIT', 'Con l''aumentare dei loro poteri, Azshara e gli Alti Nobili furono soggetti a un evidente cambiamento. La loro arrogante classe divenne sempre più indifferente e crudele nei confronti degli altri Elfi della Notte. Un oscuro manto minaccioso velava la bellezza, un tempo incantevole, di Azshara. Ella cominciò a estraniarsi dai suoi sudditi che l''adoravano e interagiva solo con i suoi fidati Sacerdoti Alti Nobili.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (648, 'itIT', 'Un giovane e brillante studioso di nome Malfurion Grantempesta, che aveva trascorso gran parte della propria vita ad analizzare gli effetti del Pozzo, cominciò a sospettare che un terribile potere stesse corrompendo gli Alti Nobili e la sua adorata regina. Anche se non poteva prevedere quale male si sarebbe abbattuto di lì a poco, sapeva che presto le vite degli Elfi della Notte sarebbero cambiate per sempre...') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1849, 'itIT', 'Dopo la partenza dei loro simili, gli Elfi della Notte tornarono a rivolgere la loro attenzione alla difesa della loro terra natale. Sentendo che stava per giungere il tempo dell''ibernazione, i Druidi si prepararono al sonno, congedandosi dalle persone amate e dalle loro famiglie.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1850, 'itIT', 'Divenuta nel frattempo Gran Sacerdotessa di Elune, Tyrande chiese al suo amato, Malfurion, di non abbandonarla per raggiungere il Sogno di Smeraldo di Ysera. Malfurion però era legato dall''onore alle Vie dei Sogni. Disse così addio alla Sacerdotessa e giurò che sarebbero rimasti una cosa sola, finché si fossero amati.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1851, 'itIT', 'Rimasta sola a proteggere Kalimdor dai pericoli del nuovo mondo, Tyrande organizzò un possente esercito composto dalle sorelle scelte tra gli Elfi della Notte. Queste guerriere, senza paura e perfettamente addestrate, giurarono di difendere Kalimdor e divennero note come Sentinelle. Anche se preferivano vigilare da sole sulle ombrose foreste di Valtetra, in caso di necessità potevano contare su numerosi alleati.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1852, 'itIT', 'Il semidio Cenarius rimase nelle vicinanze, a Radaluna presso il Monte Hyjal. I suoi figli, noti come Custodi del Boschetto, badarono agli Elfi della Notte, aiutando regolarmente le Sentinelle a mantenere la pace. Anche le timide figlie di Cenarius, le Driadi, presero a mostrarsi con maggiore frequenza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1853, 'itIT', 'Mantenere l''ordine a Valtetra assorbiva molto Tyrande e la lontananza da Malfurion la rendeva infelice. Mentre trascorrevano i lunghi secoli di sonno dei Druidi, crebbero le sue paure di una seconda invasione demoniaca. Non riusciva a scacciare la sensazione che la Legione Infuocata fosse ancora là fuori, oltre la Grande Oscurità del cielo, intenta a pianificare la sua vendetta contro gli Elfi della Notte e Azeroth.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1932, 'itIT', 'La Guardiana Aegwynn divenne sempre più potente con il passare degli anni, utilizzando le energie di Tirisfal per prolungare la propria vita. Credendo stupidamente di aver definitivamente sconfitto Sargeras, continuò a difendere il mondo dai seguaci del demoniaco sovrano per quasi novecento anni. Un giorno però, il Concilio di Tirisfal decise che il suo tempo era giunto al termine.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1933, 'itIT', 'Il Concilio ordinò ad Aegwynn di tornare a Dalaran, in modo da poter nominare un nuovo Guardiano. Aegwynn però non si fidava del Concilio e così decise di scegliere da sola il proprio successore.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1934, 'itIT', 'Piena di sé, Aegwynn decise che avrebbe avuto un figlio al quale trasmettere i propri poteri. Non aveva intenzione di consentire che l''Ordine di Tirisfal manipolasse il suo successore, come aveva tentato di fare con lei. Viaggiando verso sud Aegwynn giunse nella regione di Azeroth e lì trovò il padre perfetto per suo figlio, un abile Mago Umano di nome Nielas Aran.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1935, 'itIT', 'Aran era evocatore di corte e consigliere del Re di Azeroth. Aegwynn sedusse il Mago e concepì un figlio con lui: l''affinità naturale di Nielas per la magia avrebbe segnato il futuro del nascituro, spingendolo a percorrere la tragica strada che lo attendeva. Anche il potere di Tirisfal fu trasmesso al bambino, sebbene fosse destinato a restare dormiente fino alla sua maturità fisica.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1936, 'itIT', 'Il tempo passò e Aegwynn diede alla luce suo figlio in una selva isolata. Il piccolo ricevette il nome di Medivh, che significa "custode dei segreti" nella lingua degli Alti Elfi. Aegwynn era certa che sarebbe divenuto il nuovo Guardiano. Purtroppo lo spirito maligno di Sargeras, nascosto da tempo dentro di lei, aveva preso possesso del bimbo indifeso quando era ancora nel grembo materno. Aegwynn non poteva saperlo, ma il nuovo Guardiano era già sotto il controllo del suo nemico più pericoloso.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1937, 'itIT', 'Certa che il suo bambino fosse sano, Aegwynn portò il piccolo Medivh alla corte di Azeroth, dove lo lasciò perché fosse cresciuto dal suo padre mortale e dalla sua gente. Ella si diresse quindi nelle terre selvagge, pronta ad affrontare ciò che l''attendeva nell''aldilà. Medivh crebbe e divenne un ragazzo robusto, del tutto ignaro del potere celato in lui per via dell''eredità di Tirisfal.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1938, 'itIT', 'Sargeras attese paziente che il potere del giovane si manifestasse. Quando Medivh raggiunse l''età dell''adolescenza, egli era ormai molto famoso su Azeroth per la sua abilità nella magia e spesso si lanciava in avventure con i suoi due migliori amici: Llane, Principe di Azeroth, e Anduin Lothar, uno degli ultimi discendenti della dinastia Arathi. I tre ragazzi portavano un po'' di scompiglio ovunque nel regno, ma erano comunque ben visti dalla popolazione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1939, 'itIT', 'Quando Medivh compì i quattordici anni di età, il potere cosmico dentro di lui si risvegliò e si scontrò con lo spirito di Sargeras che albergava nella sua anima. Medivh cadde in uno stato catatonico che perdurò per diversi anni.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1940, 'itIT', 'Quando si risvegliò dal coma, si ritrovò ormai adulto e scoprì che i suoi amici, Llane e Anduin, erano divenuti i reggenti di Azeroth. Anche se era desideroso di usare i suoi nuovi, incredibili poteri per proteggere la terra che vedeva come la propria casa, l''oscuro spirito di Sargeras cercava sempre di mutare i suoi pensieri e le sue emozioni, rendendoli malvagi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1941, 'itIT', 'Sargeras prosperò nel cuore di Medivh, ormai sempre più gravato dall''ombra, sapendo che i suoi piani per la seconda invasione si avvicinavano al completamento e che sarebbe stato l''ultimo Guardiano del mondo a realizzarli.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2191, 'itIT', 'Circa 16.000 anni fa (molto tempo prima che gli Elfi della Notte scatenassero la furia della Legione Infuocata), i Troll dominavano buona parte di Kalimdor, che allora era un unico continente. Esistevano due imperi: quello dei Gurubashi, nelle giungle sudorientali, e quello degli Amani, nelle foreste della regione centrale.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2192, 'itIT', 'Esistevano altre piccole tribù che vivevano molto più a nord (nella regione ora nota come Nordania). Queste tribù fondarono una piccola nazione di nome Gundrak, senza però arrivare mai a rivaleggiare per dimensioni e ricchezza con gli imperi meridionali.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2193, 'itIT', 'Gli imperi dei Gurubashi e degli Amani si sopportavano a malapena, ma raramente finirono per combattersi apertamente. In quel tempo, il loro grande nemico comune era un terzo impero: la civiltà di Azj''aqir. Gli Aqir erano degli insettoidi intelligenti che governavano le regioni dell''estremo occidente: dotati di un intelletto molto sviluppato, avevano mire espansionistiche ed erano incredibilmente malvagi. Gli Aqir erano decisi a cancellare ogni forma di vita non-insettoide da Kalimdor.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2194, 'itIT', 'I Troll combatterono contro di loro per molte migliaia di anni, senza mai ottenere una vittoria decisiva. Alla lunga, però, grazie all''insistita azione dei Troll, il Regno degli Aqir si spezzò in due entità, con i cittadini che si spostarono in due colonie separate, nella zona meridionale e quella settentrionale del continente.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2195, 'itIT', 'Nacquero così due città-stato Aqir: Azjol-Nerub nelle lande settentrionali e Ahn''qiraj nel deserto meridionale. Anche se i Troll sospettavano l''esistenza di altre colonie Aqir a Kalimdor, la cosa non fu mai dimostrata con certezza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2196, 'itIT', 'Una volta esiliati gli insettoidi, i due imperi Troll tornarono ai loro normali rapporti. Nonostante la grande vittoria, nessuna delle due civiltà riuscì mai a espandersi in modo particolare. Alcuni antichi testi, però, parlano di una piccola fazione di Troll, staccatasi dall''Impero degli Amani, che andò a fondare una propria colonia nel cuore del continente oscuro.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2197, 'itIT', 'Là, quei prodi pionieri scoprirono il Pozzo dell''Eternità, che li tramutò in esseri dall''immenso potere. Secondo delle leggende, quei Troll divennero i primi Elfi della Notte, anche se è difficile dire se sia vero o meno.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2925, 'itIT', 'Riparazione Navi Transdimensionali per Principianti, di Jamus Kaesi$B$B<Le pagine sottili di questo libro sono fatte di un materiale brillante e sono piene di disegni molto tecnici su come mantenere e riparare una nave transdimensionale. Questa copia in particolare è aperta a un capitolo intitolato ''Problemi alla bobina di alimentazione e come evitarli''.>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2945, 'itIT', '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align="center">VERDI COLLINE DI ROVOTORTO</H1>\n<BR/>\n<H3 align="center">di Hemet Nesingwary</H3>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2946, 'itIT', 'Il nostro primo giorno andò secondo le previsioni. Avevamo trascorso la maggior parte del tempo prendendo gli accorgimenti necessari per stabilire un campo base. Avevo trovato un posto ideale vicino all''insenatura di un fiume. A giudicare dalle vecchie banchine abbandonate, questo posto doveva essere abitato tempo fa. Ma da chi? Solo il tempo può dirlo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2947, 'itIT', 'Per questa spedizione avevo scelto Ajeck Rouack e Ser S. J. Erlgadin, insieme al mio fedele servitore, Barnil Fumapietra. Avevo combattuto molte battaglie al fianco del padre di Ajeck in difesa dell''Alleanza. Vederla cresciuta mi riempiva di gioia. Suo padre l''aveva addestrata bene all''uso delle armi. Le sue abilità con l''arco mi facevano pensare che avesse sangue elfico nelle sue vene.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2948, 'itIT', 'Ser S. J. Erlgadin apparteneva all''aristocrazia degli Umani. Suo padre, il Conte Erlgadin, era noto per la sua generosità. Fu lui a battersi per migliorare le condizioni di lavoro della Gilda dei Tagliapietre durante la ricostruzione di Roccavento dopo la Seconda Grande Guerra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2949, 'itIT', 'Negli anni successivi al tradimento di Roccavento nei confronti della Gilda dei Tagliapietre, Ser Erlgadin divenne sempre più insofferente riguardo il ruolo dei nobili all''interno del Regno. Egli non voleva più mantenere la posizione che la discendenza di suo padre aveva conquistato per lui all''interno della Casata dei Nobili.$B$BMa sto divagando. Questo racconto non vuole essere un trattato politico, né una biografia. È solo un resoconto delle mie esperienze di caccia nelle colline verdi di Rovotorto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2950, 'itIT', 'Ci alzammo all''alba. Barnil cominciò a preparare la colazione. Notai che Ajeck era piuttosto distratta. Ci attendeva una lunga giornata di marcia e la nostra caccia ci avrebbe condotti vicino al pericolo. Dovevamo rimanere concentrati per non commettere errori. Tuttavia, Ajeck sembrava non riuscire a distogliere lo sguardo da Barnil, che si trovava sul bordo del fiume a risciacquare la sua gavetta.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2951, 'itIT', 'Proprio quando stavo per criticare la mancanza d''interesse di Ajeck per la strategia di caccia, lei mise mano alla sua faretra, tirò fuori una freccia e la scoccò verso il povero Barnil. Ma non era Barnil il bersaglio di Ajeck. Alle sue spalle infatti giaceva un grosso crocolisco di fiume venuto in superficie, con le fauci spalancate e la freccia di Ajeck conficcata in mezzo ai suoi due grandi occhi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2952, 'itIT', 'Ci dirigemmo verso ovest, attraverso la fitta vegetazione della giungla. Muovendoci lentamente, attraversammo il fitto fogliame in cerca di prede. La mattina era trascorsa in un silenzio desolante. Non c''era niente che si muovesse nella Valle, nemmeno una leggera brezza. Nel pomeriggio, la spedizione cominciò ad agitarsi, con Barnil che non avanzava più con la cautela di un predatore che caccia la sua preda, ma camminando goffamente e calpestando spesso foglie secche o rami caduti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2953, 'itIT', 'Dopo un altro di questi passi falsi, Erlgadin posò la mano sulla spalla di Barnil. Ajeck e io ci scambiammo una rapida occhiata, pensando che l''uomo volesse semplicemente sgridare Barnil per la sua imprudenza. Erlgadin, invece, fece un cenno lento con la testa verso un albero caduto nelle vicinanze. C''erano due occhi neri che ci fissavano, posti appena sopra una serie di zanne affilate come rasoi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2954, 'itIT', 'La bestia era un esemplare di tigre maschio di Rovotorto. Prima che potessi armare il mio archibugio, Erlgadin impugnò la sua balestra e scoccò, ma il dardo mancò il bersaglio, ferendolo sul fianco sinistro. La tigre tentò di fuggire, ma la ferita era troppo profonda. Vagò senza meta per qualche secondo, prima che Barnil le lanciasse contro un''ascia per darle il colpo di grazia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2955, 'itIT', 'L''uccisione servì a tirare su il morale della spedizione. Barnil versò a tutti dell''idromele per festeggiare. Ma la nostra euforia era destinata a durare poco. Mentre stavamo preparando la carcassa per trasportarla al campo base, fummo sorpresi da un orrendo ruggito che ci fece gelare il sangue nelle vene. Non avevo mai sentito niente di simile in tutta la mia vita.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2956, 'itIT', 'Su un precipizio roccioso in alto, definita dalla luce del sole al tramonto, riconobbi la sagoma del predatore felino più grande che avessi mai visto. Riuscii a sparare un colpo con l''archibugio senza mirare, ma il felino non si scompose e ruggì di nuovo, più forte della prima volta, quindi sparì.$B$BRaccogliemmo le nostre cose e facemmo ritorno al campo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2957, 'itIT', 'Avevo promesso ai miei compagni che il giorno seguente saremmo andati a caccia di pantere, dato che le loro pellicce sono molto richieste in tutta Azeroth. La cosa non mi sorprende, considerato che ci sono parecchi cacciatori e commercianti di pellicce che, sprezzanti del pericolo, mettono a rischio le proprie vite in nome dell''Alleanza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2958, 'itIT', 'Ajeck e Ser Erlgadin erano ansiosi di sapere come cacciare in maniera efficace con un archibugio nanico. Avevo detto ai due Umani di lasciare le loro primitive armi a distanza al campo base. Barnil e io avevamo dato loro alcune delle migliori armi da fuoco di Forgiardente.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2959, 'itIT', 'Quel giorno ci dirigemmo a sud, seguendo alcune orme fresche di pantera. Ben presto raggiungemmo un burrone attraversato da un ponte di corda. Non appena lo vidi, il pensiero corse subito agli scritti di Brann su questa regione. Avevo considerato spesso i Troll nativi una razza primitiva e ignorante, ma dopo aver ammirato questa meraviglia dell''ingegneria, non potei fare a meno di riconoscere l''abilità con la quale i costruttori Troll avevano realizzato un''impresa praticamente impossibile.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2960, 'itIT', 'Poco dopo, Ajeck individuò una pantera a sud-ovest. Ci avvicinammo senza fare rumore, con le armi spianate, pregustando già la nostra preda. Un rumore proveniente da un bosco vicino attirò subito la nostra attenzione. C''era qualcosa lì. Bastò scambiare un''occhiata con Barnil per trasmettergli i miei timori. Barnil abbassò lentamente l''archibugio. Questa preda non era per noi, ma per i nostri compagni Umani. Parecchie pantere erano cadute vittime delle nostre armi. Questa volta se ne sarebbero occupati gli Umani.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2961, 'itIT', 'Sia Ajeck che Ser Erlgadin rimasero calmi, con le armi spianate verso la densa vegetazione alla base degli alberi ondeggianti. Il sole di mezzogiorno picchiava forte sulle nostre teste. Una goccia di sudore scese lentamente sulla tempia di Erlgadin quando tirò indietro il grilletto. Al suono del clic, la fitta vegetazione si diradò e un meraviglioso esemplare di pantera nera si fece avanti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2962, 'itIT', 'Gli Umani continuarono a seguire la pantera mentre fuggiva lungo il confine della linea degli alberi. Le canne delle loro armi si muovevano in parallelo, con un tempismo perfetto. Barnil mi lanciò un''occhiata per invitarmi a intervenire, ma io feci di no con la testa. Questa preda spettava agli Umani, non a Barnil, né a me. Erlgadin esplose un fragoroso colpo, mancando completamente il bersaglio. Pare non fosse preparato al violento rinculo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2963, 'itIT', 'L''arma rinculò con violenza tra le sue braccia, andando a sbattere contro l''archibugio di Ajeck, che aveva scelto proprio quel momento per fare fuoco. Partì un colpo maldestro, diretto verso la linea degli alberi. Uno stormo di uccelli si alzò dalle fronde e volò via in ogni direzione, mentre una cortina di fumo si levava dall''albero. Rimanemmo terrorizzati a guardare mentre un enorme ramo si abbatteva sulla pantera in fuga, spezzandole la schiena.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2964, 'itIT', 'Con il passare delle settimane, le nostre scorte di pellicce di pantera e di tigre crebbero notevolmente. Decisi che era giunto il momento di passare a una nuova sfida: i raptor.$B$BGli Umani, nonostante avessero apprezzato i miei insegnamenti e quelli di Barnil, decisero di non cacciare con le armi da fuoco. Ajeck si trovava più a proprio agio con l''arco, mentre Ser Erlgadin non si separava mai dalla sua fida balestra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2965, 'itIT', 'Ci mettemmo in marcia alle prime luci dell''alba, diretti a sud, oltre le Rovine di Tkashi. Barnil temeva che ci saremmo imbattuti nei membri della Tribù Scalporosso. Gli spiegai che gli Scalporosso erano impegnati a distruggere la loro tribù rivale, quella dei Fendicranio. Inutile dire che le mie parole non gli furono di alcun sollievo. Tuttavia pensavo che con un archibugio carico, una sacca piena di polvere da sparo e tre cacciatori letali al mio fianco non ci fosse da temere alcuna imboscata nemica.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2966, 'itIT', 'Avevo affrontato un Infernale gigante in battaglia, con l''armata della Legione Infuocata che avanzava da tutte le direzioni. Un gruppo di Troll turbolenti per me era innocuo quanto un coniglio sulle colline di Dun Morogh.$B$BSuperammo le Rovine di Tkashi senza problemi, con grande sollievo di Barnil. Il gruppo poi proseguì verso ovest, in direzione del Grande Mare, girando intorno alle Rovine di Zul''Kunda a sud. Mentre stavamo per arrampicarci sugli alti promontori a picco sul mare, scoprimmo il nostro primo raptor.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2967, 'itIT', 'La bestia non si era accorta della nostra presenza. L''unico segnale che ricevette da noi fu un proiettile in mezzo agli occhi. Ser Erlgadin si lasciò andare a un *urrà*, mentre Ajeck annuiva rivolta verso di me in segno di approvazione. Rovistai nella mia sacca in cerca della pipa, sperando di fare qualche tiro per festeggiare. Barnil si affrettò a recuperare la carcassa del raptor dal fianco della collina. Io fissai la bestia morta con la soddisfazione che accompagna l''uccisione di ogni grossa preda.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2968, 'itIT', 'Peccato che non abbia potuto bearmi di quel trofeo troppo a lungo. Non appena rivolsi lo sguardo verso l''orizzonte, vidi apparire diverse sagome sullo sfondo della collina, proprio sopra il povero Barnil.$B$B*Scappa, Barnil!* gli urlai. Ajeck, Ser Erlgadin e io sparammo raffiche di proiettili, frecce e dardi verso Barnil e i raptor che lo inseguivano, riuscendo a ucciderne uno nella confusione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2969, 'itIT', 'I nostri colpi alla cieca erano bastati a coprire la fuga di Barnil e a farlo scendere dalla collina per riunirsi al resto del gruppo. Ci dirigemmo nella giungla, dove un gruppo di Raptor Codafrusta seguiva ogni nostra mossa. Ora i cacciatori erano diventati prede.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2970, 'itIT', 'Avevo condotto il gruppo verso il mare, nella speranza che la spiaggia fosse un rifugio sicuro dai raptor. Nella fretta ci eravamo spinti troppo a nord, in posizione elevata e precaria, ma ormai il danno era stato fatto ed era tutta colpa mia. Ci fermammo poco prima di un promontorio a picco, con i raptor che ci inseguivano da vicino.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2971, 'itIT', 'Io feci un passo in avanti, lentamente, con l''arma spianata. Avevo condotto alla morte questi coraggiosi cacciatori e avrei dato la mia vita per difenderli. I Raptor Codafrusta sono creature particolarmente feroci e sanguinarie. Erano molto più numerosi di noi, ma non avrei mai permesso che uccidessero me e i miei compagni senza prima versare un po'' del loro stesso sangue.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2972, 'itIT', 'Ajeck e Ser Erlgadin imbracciarono le loro armi e si posizionarono ai miei fianchi, con il mare alle spalle. Barnil emise un sospiro di rassegnazione e tirò fuori la sua ascia. I Codafrusta ci erano quasi addosso. Avevano rallentato la falcata. Stavano studiando la loro preda perché sapevano che eravamo in trappola.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2973, 'itIT', 'Quello che accadde dopo ha dell''incredibile. Di fianco a noi udimmo il classico ruggito spaventoso della grande Tigre Bianca. Nonostante il loro numero, i raptor fuggirono in tutte le direzioni. Vedemmo un breve lampo bianco: era la tigre che ci sfrecciava accanto gettandosi sui raptor. Non ci fu bisogno di dire nulla. Tutti e quattro i membri del gruppo sapevano che era il momento di darsela a gambe.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2974, 'itIT', 'Raggiungemmo di corsa il campo base, senza mai rallentare. Più tardi quella notte ci sedemmo intorno al fuoco per riposare, consapevoli di essere vivi per miracolo. D''altronde questi sono i rischi di chi pratica la caccia grossa. Eppure ognuno di noi sa che, a un certo punto, andrà incontro al proprio destino per colpa dei denti aguzzi di un raptor. Per quanto mi riguarda, sono felice che non sia capitato nelle colline verdi di Rovotorto.$B$BFine') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3157, 'itIT', 'Skor''zad sbirciò nervosamente da dietro la colonna. Come aveva pensato, la vide fluttuare là, da sola nella sua stanza. Aveva preso la decisione giusta visitando la camera privata della Banshee così tardi, di notte? I negromanti lo avrebbero sicuramente rinchiuso, se lo avessero scoperto. Ma la cosa peggiore era che non sapeva se i suoi sentimenti erano ricambiati... e Dama Sidnari era famosa per il suo carattere irascibile.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3158, 'itIT', 'I pochi dubbi rimasti allo Zombi vennero però spazzati via non appena egli vide quanto era bella. I suoi lineamenti elfici, lascito di ciò che era stata in una vita passata, erano messi in risalto dalle ferite e dalle cicatrici che solcavano il suo volto. La pelle violacea, quasi trasparente, era coperta da panni cadenti e frugali che avvolgevano la sua esile figura. La sua fredda carne si fondeva dolcemente con l''effimero e il suo torso senza gambe appoggiava su una sfera di energia bluastra, sospesa alcuni centimetri sopra il pavimento di granito. Skor''zad si rilassò un po'', asciugandosi il sudore e i fluidi che colavano sulla sua fronte.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3159, 'itIT', 'Apparentemente ignara della sua presenza, lei si avvicinò all''unica finestra nella stanza e osservò il campo di battaglia. Dinanzi a lei si stendeva la desolazione. Meno di sei ore prima le grida dei bambini umani avevano trafitto l''aria, ma ora... restava solo il dolce silenzio della morte.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3160, 'itIT', 'Il vento scompigliò i suoi capelli, attorcigliando le sue trecce simili a vermi nelle sue cavità oculari. Skor''zad, accortosi che il desiderio lo aveva portato fuori dal suo nascondiglio, si forzò a tornare dietro la colonna, terrorizzato all''idea che l''Oscura Berciatrice l''avesse visto. E proprio questo accadde, anche se lui non aveva ragione di essere impaurito.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3161, 'itIT', '"Skor''zad," disse. "Ti stavo aspettando. Oggi hai combattuto con valore.". La Banshee gettò uno sguardo da sopra la sua putrefatta spalla destra, lasciando che le sue vesti si aprissero leggermente. "Sei qui per avere... la tua ricompensa?".') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3162, 'itIT', '<Le pagine seguenti sembrano incollate.>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3218, 'itIT', 'Mi è stato segnalato che alcuni dei nuovi Cavalieri della Morte sono ancora tormentati dalle memorie delle loro vite passate. Voglio dire alle loro menti inquiete di non tormentarsi, perché io per primo sono afflitto dagli errori del mio passato. Nel Flagello, però, ho trovato l''assoluzione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3219, 'itIT', 'Nella mia ignoranza, un tempo ero un Paladino al servizio dell''odiata Luce. Accecato dalle menzogne sulla speranza, ho lasciato mia moglie e le mie due figlie a casa per indagare sulla presenza del Flagello nella nostra zona. Abbiamo esplorato i boschi per settimane, senza trovare nulla. All''arrivo dell''inverno ancora non sapevamo niente del nemico, quindi abbiamo deciso di tornare a casa.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3220, 'itIT', 'Quando arrivammo sul crinale, ci si parò dinanzi agli occhi una visione orribile: il villaggio era in fiamme, devastato. Corsi alla mia casa: una rozza freccia era conficcata all''esterno della porta. Troppo sconvolto per badarvi entrai, solo per trovare i resti della mia famiglia a terra, bruciati oltre ogni possibile riconoscimento. Mi girai, vinto dall''orrore, e vidi i graffi sulla porta fatti dalle loro unghie disperate. I segni più piccoli erano quelli delle mie bambine.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3221, 'itIT', 'In seguito scoprii che, durante la nostra assenza, si era diffusa la voce che un portatore della Piaga fosse nascosto nel villaggio. La Crociata Scarlatta aveva quindi radunato tutti gli abitanti per poi bruciarli vivi. Per quanto fosse stata grande la loro crudeltà, ne sentii nascere una ancora superiore dentro di me: giurai di dare la caccia ai Crociati e di farli soffrire sotto la furia della mia lama.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3222, 'itIT', 'Mi fu quindi ordinato di riunirmi al resto del mio gruppo. Sentivo che alcuni erano animati dalla mia stessa disperazione, dalla mia furia, ma i capi ci ordinarono di procedere verso la destinazione prefissata. Poco dopo il calar della notte, sentimmo dei non morti fra gli alberi e fummo attaccati da un gruppo di soldati del Flagello.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3223, 'itIT', 'Li colpii meccanicamente, ma per ognuno che cadeva, altri due sbucavano dalle colline. Così ci trovammo sorpresi dal Flagello a lungo cercato proprio nel momento in cui non eravamo pronti ad affrontarlo. I miei alleati caddero, vittime di ferite e sfinimento. Il Flagello era troppo numeroso perché fosse possibile resistere.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3224, 'itIT', 'Mentre il nemico mi colpiva, ricordai di aver giocato con le mie figlie in quello stesso bosco. La cosa mi riempì d''odio: perché esistono questi ricordi? Erano un''illusione, utile solo a distrarmi dalla realtà del dolore e della morte. Le mie figlie non c''erano più e il Flagello era ovunque. La morte è l''unica conclusione di ogni racconto mortale. L''uso del proprio potere per proteggere qualcuno porta soltanto al fallimento: il successo è riservato a chi persegue un altro fine...') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3225, 'itIT', 'In quel preciso momento decisi di servire il Re dei Lich, l''araldo della vittoria nella nostra era. Egli mi liberò dalle odiose sensazioni umane che mi avevano tormentato fino ad allora e così rinacqui come Cavaliere della Morte. Non c''è alcuna forza che possa fermare me e miei fratelli. Non esiste sconfitta così bruciante da fiaccare la mia risolutezza. Purificato dal Flagello, sono pronto a saziare la mia sete di morte in tutta Azeroth.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3235, 'itIT', 'Annotazione 1:$B$Bil fervore del Gran Generale ha infiammato i popolani! Le forze della Crociata diventano più potenti di giorno in giorno e sempre più uomini validi si uniscono alla nostra causa. Siamo una possente spada pronta ad abbattersi su Nordania per porre fine a quest''infinita battaglia. Pensieri foschi ci tormentano, però. Con il Bastione Scarlatto in fiamme, non posso fare a meno di sentire la morte nel vento che soffia alle nostre spalle.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3236, 'itIT', 'Annotazione 15:$B$BAbbendis è impazzita. Ha intenzione di causare uno scisma nella Crociata per attaccare la cittadella del Re dei Lich con un manipolo dei nostri seguaci più fedeli! Che abbia intenzione di lasciar bruciare Nuova Avalon e la Mano di Tyr, mentre lei veleggia verso il margine del mondo con i nostri ultimi difensori?') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3237, 'itIT', 'Annotazione 23:$B$Bil mattino è luminoso, picconi e aratri rilucono mentre uomini e donne lavorano nelle miniere e nei campi. Un''ombra è giunta: una necropoli. Questa non è Naxxramas. Il Flagello si è stabilito qui vicino e Abbendis ci ha ordinato di combattere fino all''ultimo uomo. Ho giurato la mia fedeltà solo per cadere sotto questo nemico, mentre Abbendis si ritira?') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3238, 'itIT', '<Ripiegata nell''ultima pagina del diario c''è una mappa disegnata in fretta. Sembra che l''autore avesse pianificato di nuotare lungo la costa nordorientale di Lordaeron, fino a raggiungere le Radure di Tirisfal!>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2151, 'itIT', 'Arellas Fogliardente$BGran Mago della Crociata Scarlatta$BCittadino di Quel''Thalas$BImpegnato in uno scontro eterno con il Negromante Diesalven') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2152, 'itIT', 'Ammiraglio Barean Zefiro$BGran Ammiraglio della Flotta Scarlatta$BCittadino di Kul Tiras$BDisperso al largo della Costa Gelida di Nordania') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2153, 'itIT', 'Dorgar Fortefronte$BGuerriero della Crociata Scarlatta$BSignore delle Caverne Rosse$BVisto l''ultima volta nelle Montagne d''Alterac') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2172, 'itIT', 'Ferren Marcus$BGran Abate del Monastero Scarlatto$BCittadino di Stratholme$BUcciso durante la difesa del Monastero Scarlatto dal primo Assalto della Caldamarea') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2173, 'itIT', 'Harthal Verosguardo$BSignore dei Paladini della Crociata Scarlatta$BCittadino di Azeroth, Cavaliere della Mano d''Argento$BVisto l''ultima volta mentre entrava nella città maledetta di Stratholme') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2174, 'itIT', 'Holia Scudasole$BProtettrice della Crociata Scarlatta$BUccisa mentre combatteva contro il Signore del Terrore Beltheris') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2175, 'itIT', 'Invar Monobraccio$BPrimo Capo Assassino della Crociata Scarlatta$BCittadino di Dalaran$BVisto l''ultima volta sulle coste di Nordania') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2176, 'itIT', 'Orman di Stromgarde$BPrimo Capitano Generale della Crociata Scarlatta$BCittadino di Stromgarde$BDisperso alle bocche del Ghiacciaio delle Ossa') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2177, 'itIT', 'Valea Doppialama$BGuerriera della Crociata Scarlatta$BCittadina di Alterac$BVista l''ultima volta nel cuore delle Terre Infette Orientali') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2178, 'itIT', 'Yana Lanciarossa$BSecondo Capo Assassino della Crociata Scarlatta$BCittadina di Dalaran$BDispersa nelle Radure di Tirisfal') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1431, 'itIT', 'Vorfalk Zuccadiferro$B$BVorfalk lavora nel magazzino del Torvo Beone. La sua devozione verso i Guardiani Oscuri è profonda.$B$BPossa il suo spirito vivere per sempre.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1432, 'itIT', 'Bethek Cigliatonanti$B$BI viaggi di Bethek lo portano fin nelle profondità di Roccianera. I segreti della montagna lo chiamano.$B$BPossa il suo spirito non vacillare mai.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1435, 'itIT', 'Ofgut Pugnosaldo\n\nNon si contano più coloro che sono caduti di fronte al martello del Guardiano Oscuro Ofgut.\n\nI soldati della Guarnigione Occidentale lo temono e si inchinano al suo passaggio. D''altronde, chi mai riuscirebbe a guardarlo negli occhi e a vedere i segreti sussurrati dalla Chiave Oscura?') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1436, 'itIT', 'Pelver Piedenero$B$BIl Guardiano Oscuro Pelver è il nostro discepolo più rispettato. Egli ha portato la Chiave più a lungo di chiunque altro, pagandolo a caro prezzo. Quando è chiamato a reggere il proprio fardello, viene sorvegliato nelle Residenze.$B$BIl suo sacrificio è molto rispettato ed egli rimarrà nei nostri cuori per molti anni... dopo che le tenebre se lo saranno preso.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2104, 'itIT', 'Benché ne fossero uscite vincitrici, le razze mortali si ritrovarono in un mondo devastato dalla guerra. Il Flagello e la Legione Infuocata avevano annientato ogni forma di civiltà a Lordaeron e avevano quasi fatto altrettanto a Kalimdor. C''erano foreste da risanare, rancori da sopire e case da ricostruire. La guerra aveva ferito profondamente tutte le razze, che avevano però deciso di restare unite per un nuovo inizio, confermando la difficile tregua fra Alleanza e Orda.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2105, 'itIT', 'Thrall guidò gli Orchi sul continente di Kalimdor, dove fondarono una nuova nazione con l''aiuto dei Tauren. Dopo aver chiamato la nuova terra Durotar in onore del padre di Thrall assassinato, gli Orchi intrapresero la ricostruzione della loro società.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2106, 'itIT', 'Ora che la maledizione demoniaca era svanita, l''Orda aveva perso la sua indole distruttrice e bellicosa e rappresentava un''unione di clan più interessati alla sopravvivenza e alla prosperità che alla conquista. Aiutati dai nobili Tauren e dagli astuti Troll della Tribù Lanciascura, Thrall e i suoi Orchi sognavano una nuova era di pace nelle loro terre.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2107, 'itIT', 'Le forze residue dell''Alleanza, sotto la guida di Jaina Marefiero, si insediarono nella zona meridionale di Kalimdor. Al largo della costa orientale di Acquemorte crearono la città portuale di Theramore. Là gli Umani e i Nani loro alleati cercarono di sopravvivere in una terra che era loro ostile. Anche se gli abitanti di Durotar e Theramore rispettarono la tregua, la fragile serenità coloniale non era destinata a durare.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2108, 'itIT', 'La pace fra Orchi e Umani venne infatti scossa dall''arrivo di una grande flotta dell''Alleanza a Kalimdor. La possente armata, agli ordini del Grande Ammiraglio Daelin Marefiero (il padre di Jaina), era salpata da Lordaeron prima che Arthas distruggesse il regno. Dopo molti mesi di navigazione, l''Ammiraglio Marefiero era in cerca di sopravvissuti dell''Alleanza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2109, 'itIT', 'La flotta di Marefiero rappresentava una grave minaccia alla stabilità della regione. In quanto famoso eroe della Seconda Guerra, il padre di Jaina era un acerrimo nemico dell''Orda e si mostrò intenzionato a distruggere Durotar prima che gli Orchi consolidassero la loro posizione nell''area.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2110, 'itIT', 'Il Grande Ammiraglio costrinse Jaina a prendere una terribile decisione: sostenerlo nella battaglia contro gli Orchi, tradendo così i propri nuovi alleati, oppure sfidare il proprio padre per mantenere la fragile pace faticosamente raggiunta tra Alleanza e Orda. Dopo attenta riflessione, Jaina scelse la seconda strada, aiutando Thrall a sconfiggere suo padre ormai uscito di senno.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2111, 'itIT', 'Purtroppo l''Ammiraglio Marefiero morì in battaglia prima che Jaina potesse riconciliarsi con lui o dimostrargli che gli Orchi non erano più dei mostri assetati di sangue. Questi ultimi, in cambio della fedeltà dimostrata da Jaina, permisero al suo esercito di tornare a Theramore sano e salvo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
